<template>
  <component v-if="choice" :is="screenComponent" :second-approval="choice.secondApproval" />
  <div v-else class="flex flex-center q-pa-xl">
    <q-spinner size="2em" />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { documentListApiService } from 'src/services';
import { useDocAttributesStore } from 'src/store/Document/attributes.store';
import { useActiveScreenStore } from 'src/store/Router/active-screen.store';
import { approve_before_export_v2 } from 'src/constants';
import { notify } from 'src/components/notifications/notify';
import { paths } from 'src/router/paths';
import { resolveApprovalScreen, type ApprovalScreenChoice } from './resolveApprovalScreen';
import { APPROVAL_SCREENS } from './screens';

interface DocumentRow {
  id: string;
  status: string;
  doc_type: string;
}

export default defineComponent({
  name: 'ApprovalDispatcher',
  setup() {
    return { activeScreen: useActiveScreenStore(), attributes: useDocAttributesStore() };
  },
  data() {
    return { choice: null as ApprovalScreenChoice | null };
  },
  computed: {
    screenComponent() {
      return this.choice ? APPROVAL_SCREENS[this.choice.screen] : null;
    },
  },
  async mounted() {
    await this.resolveScreen();
  },
  beforeUnmount() {
    if (this.choice && this.activeScreen.screen === this.choice.screen) this.activeScreen.clear();
  },
  methods: {
    async resolveScreen() {
      const raw = this.$route.params.id;
      const docId = Array.isArray(raw) ? raw[0] : String(raw);
      let row: DocumentRow | null;
      try {
        row = await this.loadDocumentRow(docId);
        if (row) await this.attributes.getDocTypeAllSettings();
      } catch (error) {
        logError(error, { source: 'ApprovalDispatcher.resolveScreen', docId });
        this.leaveWithError('ERROR_FETCHING_LINKED_DOCUMENT');
        return;
      }
      if (!row) {
        this.leaveWithError('messages_DOCUMENT_NOT_FOUND');
        return;
      }
      const approvalV2Enabled = Boolean(
        this.attributes.getSettingsByDocTypeAndSettingKey(row.doc_type, approve_before_export_v2),
      );
      this.choice = resolveApprovalScreen({ status: row.status, approvalV2Enabled });
      this.activeScreen.setScreen(this.choice.screen);
    },
    async loadDocumentRow(docId: string): Promise<DocumentRow | null> {
      const res = await documentListApiService.getList('?document_ids=' + docId);
      return res?.documents?.[0] ?? null;
    },
    leaveWithError(messageKey: string) {
      notify.error(this.$t(messageKey));
      this.$router.replace(paths.dashboard());
    },
  },
});
</script>
