export type ApprovalScreen = 'approval-v2' | 'approval-v3';

export interface ApprovalScreenInput {
  status: string;
  approvalV2Enabled: boolean;
}

export interface ApprovalScreenChoice {
  screen: ApprovalScreen;
  secondApproval: boolean;
}

const SECOND_APPROVAL_STATUS = 'approved_pending_second_approval';

// The doc-type setting APPROVE_BEFORE_EXPORT_V2 selects the *v3* page; the names
// were never aligned and both are still in use.
export function resolveApprovalScreen({ status, approvalV2Enabled }: ApprovalScreenInput): ApprovalScreenChoice {
  return {
    screen: approvalV2Enabled ? 'approval-v3' : 'approval-v2',
    secondApproval: status === SECOND_APPROVAL_STATUS,
  };
}
